function c(string $k,mixed $d=null):mixed { global $cfg; return $cfg[$k]??$d; }
function pdo():PDO {
 static $db=null;
 if (!$db) $db=new PDO('mysql:host='.c('DB_HOST','localhost').';port='.(int)c('DB_PORT',3306).';dbname='.c('DB_NAME','fileweb').';charset=utf8mb4',(string)c('DB_USER',''),(string)c('DB_PASSWORD',''),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
 return $db;
}
function q(string $s,array $a=[]):PDOStatement { $st=pdo()->prepare($s);$st->execute($a);return $st; }
function one(string $s,array $a=[]):?array { $r=q($s,$a)->fetch();return $r===false?null:$r; }
function rows(string $s,array $a=[]):array { return q($s,$a)->fetchAll(); }
function out(mixed $v,int $status=200):never { http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('X-Content-Type-Options: nosniff');echo json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit; }
function err(int $s,string $m):never { out(['error'=>$m],$s); }
function input():array { $v=json_decode(file_get_contents('php://input')?:'{}',true);return is_array($v)?$v:[]; }
function b64(string $s):string{return rtrim(strtr(base64_encode($s),'+/','-_'),'=');}
function jwt(int $id):string{$h=b64('{"alg":"HS256","typ":"JWT"}');$p=b64(json_encode(['id'=>$id,'exp'=>time()+2592000]));return $h.'.'.$p.'.'.b64(hash_hmac('sha256',$h.'.'.$p,(string)c('JWT_SECRET'),true));}
function user():array{$h = $_SERVER['HTTP_AUTHORIZATION']
