?? $_SERVER['Authorization']
?? (function_exists('getallheaders')
    ? (getallheaders()['Authorization'] ?? '')
    : '');;if(!preg_match('/^Bearer\\s+(.+)$/i',$h,$m))err(401,'Non authentifié');$a=explode('.',trim($m[1]));if(count($a)!==3)err(401,'Non authentifié');$sig=b64(hash_hmac('sha256',$a[0].'.'.$a[1],(string)c('JWT_SECRET'),true));if(!hash_equals($sig,$a[2]))err(401,'Non authentifié');$p=json_decode(base64_decode(strtr($a[1],'-_','+/')),true);if(!is_array($p)||(int)($p['exp']??0)<time())err(401,'Non authentifié');$u=one('SELECT id,username,role,display_name FROM users WHERE id=?',[(int)$p['id']]);if(!$u)err(401,'Non authentifié');return $u;}
function admin(array $u):void{if($u['role']==='user')err(403,'Réservé aux administrateurs.');}
function len(string $s):int{return function_exists('mb_strlen')?mb_strlen($s,'UTF-8'):strlen($s);}
function sub(string $s,int $n):string{return function_exists('mb_substr')?mb_substr($s,0,$n,'UTF-8'):substr($s,0,$n);}
