function validName(mixed $s):bool{return is_string($s)&&trim($s)!==''&&len($s)<=255&&!preg_match('~[\\\\/]~u',$s);}
function validUser(mixed $s):bool{return is_string($s)&&preg_match('/^[\\w.-]{3,32}$/',$s)===1;}
function validPw(mixed $s):bool{return is_string($s)&&strlen($s)>=6;}
function mime(string $n):string{$m=['html'=>'text/html','htm'=>'text/html','md'=>'text/markdown','markdown'=>'text/markdown','txt'=>'text/plain','css'=>'text/css','js'=>'text/javascript','json'=>'application/json','csv'=>'text/csv','xml'=>'application/xml','png'=>'image/png','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','gif'=>'image/gif','webp'=>'image/webp','svg'=>'image/svg+xml','bmp'=>'image/bmp','ico'=>'image/x-icon','pdf'=>'application/pdf','zip'=>'application/zip'];return $m[strtolower(pathinfo($n,PATHINFO_EXTENSION))]??'application/octet-stream';}
function init():void{
 $sql=[
 "CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(32) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,role ENUM('root','admin','user') NOT NULL DEFAULT 'user',display_name VARCHAR(80) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB",
 "CREATE TABLE IF NOT EXISTS nodes(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,private_owner INT NULL,parent_id INT NULL,name VARCHAR(255) NOT NULL,type ENUM('file','folder') NOT NULL,mime VARCHAR(100) NULL,content LONGBLOB NULL,size BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(parent_id),FOREIGN KEY(parent_id) REFERENCES nodes(id) ON DELETE CASCADE) ENGINE=InnoDB",
 "CREATE TABLE IF NOT EXISTS user_groups(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(64) NOT NULL UNIQUE) ENGINE=InnoDB",
 "CREATE TABLE IF NOT EXISTS group_members(group_id INT NOT NULL,user_id INT NOT NULL,PRIMARY KEY(group_id,user_id),FOREIGN KEY(group_id) REFERENCES user_groups(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB",
 "CREATE TABLE IF NOT EXISTS perms(id INT AUTO_INCREMENT PRIMARY KEY,node_id INT NOT NULL,subject_type ENUM('user','group','all') NOT NULL,subject_id INT NOT NULL DEFAULT 0,can_view TINYINT(1) NOT NULL DEFAULT 1,can_edit TINYINT(1) NOT NULL DEFAULT 0,UNIQUE(node_id,subject_type,subject_id),FOREIGN KEY(node_id) REFERENCES nodes(id) ON DELETE CASCADE) ENGINE=InnoDB",
 "CREATE TABLE IF NOT EXISTS share_links(id INT AUTO_INCREMENT PRIMARY KEY,node_id INT NOT NULL UNIQUE,token CHAR(64) NOT NULL UNIQUE,enabled TINYINT(1) NOT NULL DEFAULT 1,editor_only TINYINT(1) NOT NULL DEFAULT 0,created_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(node_id) REFERENCES nodes(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB"
 ];foreach($sql as $s)pdo()->exec($s);
 foreach(['users'=>['role'=>"ALTER TABLE users ADD COLUMN role ENUM('root','admin','user') NOT NULL DEFAULT 'user'",'display_name'=>'ALTER TABLE users ADD COLUMN display_name VARCHAR(80) NULL'],'nodes'=>['private_owner'=>'ALTER TABLE nodes ADD COLUMN private_owner INT NULL']] as $t=>$cols)foreach($cols as $col=>$alter){$r=one('SELECT COUNT(*) n FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND COLUMN_NAME=?',[$t,$col]);if(!(int)$r['n'])pdo()->exec($alter);}
 $fks=rows("SELECT CONSTRAINT_NAME c FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='nodes' AND COLUMN_NAME='user_id' AND REFERENCED_TABLE_NAME='users'");
 foreach($fks as $fk)pdo()->exec('ALTER TABLE nodes DROP FOREIGN KEY `'.str_replace('`','',$fk['c']).'`');
 if($fks)pdo()->exec('ALTER TABLE nodes MODIFY user_id INT NULL');
 $root=one("SELECT id FROM users WHERE role='root' LIMIT 1");if($root)return;
 $pw=rtrim(strtr(base64_encode(random_bytes(12)),'+/','-_'),'=');$hash=password_hash($pw,PASSWORD_BCRYPT);
 if($root)q('UPDATE users SET password_hash=? WHERE id=?',[$hash,$root['id']]);else{$old=one("SELECT id FROM users WHERE username='root'");if($old)q("UPDATE users SET role='root',password_hash=? WHERE id=?",[$hash,$old['id']]);else q("INSERT INTO users(username,password_hash,role) VALUES('root',?,'root')",[$hash]);}
 $d=__DIR__.'/storage';if(!is_dir($d))mkdir($d,0700,true);file_put_contents($d.'/.htaccess',"Require all denied\n");file_put_contents($d.'/initial-root.txt',"Compte root FBI\nIdentifiant : root\nMot de passe : $pw\nSupprimez ce fichier après connexion.\n");@chmod($d.'/initial-root.txt',0600);
}
function ctx(array $u):array{
 $ns=rows('SELECT id,parent_id,name,type,private_owner FROM nodes');$ps=rows('SELECT node_id,subject_type,subject_id,can_view,can_edit FROM perms');$gm=rows('SELECT group_id FROM group_members WHERE user_id=?',[$u['id']]);$groups=array_fill_keys(array_map(fn($x)=>(int)$x['group_id'],$gm),true);$by=$kids=$acl=$acc=[];
 foreach($ns as $n){$n['id']=(int)$n['id'];$n['parent_id']=$n['parent_id']===null?null:(int)$n['parent_id'];$n['private_owner']=$n['private_owner']===null?null:(int)$n['private_owner'];$by[$n['id']]=$n;$kids[$n['parent_id']??0][]=$n['id'];}
 foreach($ps as $p)$acl[(int)$p['node_id']][]=$p;
 $hit=fn($p)=>$p['subject_type']==='all'||($p['subject_type']==='user'&&(int)$p['subject_id']===(int)$u['id'])||($p['subject_type']==='group'&&isset($groups[(int)$p['subject_id']]));
 $calc=function($id)use(&$calc,&$acc,$by,$acl,$hit,$u){if(isset($acc[$id]))return $acc[$id];$n=$by[$id];$par=$n['parent_id']?$calc($n['parent_id']):['v'=>true,'av'=>true,'ae'=>true];if($n['private_owner']!==null){$ok=$n['private_owner']===(int)$u['id'];return $acc[$id]=['v'=>$ok,'e'=>$ok,'av'=>$ok,'ae'=>$ok];}$rules=$acl[$id]??null;$av=$rules?count(array_filter($rules,fn($p)=>$hit($p)&&(int)$p['can_view']))>0:$par['av'];$ae=$rules?count(array_filter($rules,fn($p)=>$hit($p)&&(int)$p['can_edit']))>0:$par['ae'];$v=$u['role']!=='user'||($av&&$par['v']);return $acc[$id]=['v'=>$v,'e'=>$u['role']!=='user'||($ae&&$v),'av'=>$av,'ae'=>$ae];};
 foreach(array_keys($by) as $id)$calc($id);return compact('by','kids','acl','acc');
}
function can(array $c,int $id,string $l):bool{return !empty($c['acc'][$id][$l]);}
function treeIds(array $c,int $id):array{$o=[];$s=[$id];while($s){$x=array_pop($s);$o[]=$x;foreach($c['kids'][$x]??[] as $k)$s[]=$k;}return $o;}
function place(array $c,array $u,mixed $parent,bool $private):array{if($parent!==null&&$parent!==''&&(int)$parent!==0){$id=(int)$parent;$p=$c['by'][$id]??null;if(!$p||$p['type']!=='folder'||!can($c,$id,'v'))return ['err'=>[404,'Dossier introuvable.']];if(!can($c,$id,'e'))return ['err'=>[403,'Ce dossier est en lecture seule.']];return ['parent'=>$id,'owner'=>$p['private_owner']];}return ['parent'=>null,'owner'=>$private?(int)$u['id']:null];}
function addNode(int $uid,?int $parent,string $name,string $type,string $data='',?int $owner=null):int{q('INSERT INTO nodes(user_id,private_owner,parent_id,name,type,mime,content,size) VALUES(?,?,?,?,?,?,?,?)',[$uid,$owner,$parent,$name,$type,$type==='file'?mime($name):null,$type==='file'?$data:null,$type==='file'?strlen($data):0]);return (int)pdo()->lastInsertId();}
function copyNode(array $c,int $id,int $uid,?int $parent,string $name,?int $owner):int{$n=one('SELECT type,content FROM nodes WHERE id=?',[$id]);$new=addNode($uid,$parent,$name,$n['type'],$n['content']??'',$owner);if($n['type']==='folder')foreach($c['kids'][$id]??[] as $k)if(can($c,$k,'v'))copyNode($c,$k,$uid,$new,$c['by'][$k]['name'],$owner);return $new;}
function zipAdd(array $c,int $id,ZipArchive $z,string $prefix=''):void{$n=$c['by'][$id];if($n['type']==='file'){$r=one('SELECT content FROM nodes WHERE id=?',[$id]);$z->addFromString($prefix.$n['name'],$r['content']??'');}else{$z->addEmptyDir($prefix.$n['name']);foreach($c['kids'][$id]??[] as $k)if(can($c,$k,'v'))zipAdd($c,$k,$z,$prefix.$n['name'].'/');}}
function target(array $u,int $id):array{$t=one('SELECT id,role FROM users WHERE id=?',[$id]);if(!$t)err(404,'Compte introuvable.');if($t['role']==='root'||(int)$t['id']===(int)$u['id']||($u['role']!=='root'&&$t['role']!=='user'))err(403,'Action non autorisée sur ce compte.');return $t;}
function share(string $token):never{$r=one('SELECT sl.editor_only,n.name,n.mime,n.content FROM share_links sl JOIN nodes n ON n.id=sl.node_id WHERE sl.token=? AND sl.enabled=1',[$token]);if(!$r){http_response_code(404);exit('Lien invalide ou désactivé.');}$name=htmlspecialchars($r['name'],ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$data=$r['content']??'';$mime=$r['mime']?:'text/plain';$e=htmlspecialchars($data,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');header("Content-Security-Policy: default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data: https:; frame-src data:; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'");header('Cache-Control: no-store');header('Content-Type: text/html; charset=utf-8');if(str_starts_with($mime,'image/'))$preview='<img style="max-width:100%;max-height:80vh" src="data:'.htmlspecialchars($mime).';base64,'.base64_encode($data).'">';elseif($mime==='application/pdf')$preview='<iframe style="width:100%;height:80vh" sandbox src="data:application/pdf;base64,'.base64_encode($data).'"></iframe>';elseif(in_array(strtolower(pathinfo($r['name'],PATHINFO_EXTENSION)),['html','htm']))$preview='<iframe style="width:100%;height:80vh" sandbox srcdoc="'.$e.'"></iframe>';else $preview='<pre style="white-space:pre-wrap;overflow-wrap:anywhere">'.$e.'</pre>';$editor=$r['editor_only']?'<textarea id="edit" style="width:100%;height:180px">'.$e.'</textarea><button id="save">Enregistrer</button><span id="status"></span><script>save.onclick=async()=>{let r=await fetch("/api/public-share/'.$token.'",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({content:edit.value})});status.textContent=r.ok?"Enregistré.":"Erreur";}</script>':'';echo '<!doctype html><html lang="fr"><meta charset="utf-8"><title>'.$name.'</title><body style="background:#111a22;color:#e6edf3;font:15px system-ui;padding:28px"><h1>'.$name.'</h1>'.$preview.$editor.'</body></html>';exit;}

if(strlen((string)c('JWT_SECRET',''))<32 || str_contains((string)c('JWT_SECRET',''),'REMPLACEZ'))err(503,'Définissez une clé JWT_SECRET longue et privée dans config.php.');
